"use strict";function setActiveNavLink(){const e=document.body.dataset.page;e&&document.querySelectorAll(".navbar-nav .nav-link").forEach(t=>{const o=t.getAttribute("href"),n="home"===e&&("index.html"===o||"./"===o||"/"===o)||"home"!==e&&o&&o.includes(e);t.classList.toggle("active",n)})}function initTopBar(){const e=document.getElementById("closeTopBar"),t=document.getElementById("topBar"),o=document.getElementById("topBarText");o&&"undefined"!=typeof SITE_CONFIG&&(o.textContent=SITE_CONFIG.topBarText),e&&t&&e.addEventListener("click",()=>t.classList.add("hidden"))}function initHeroSwiper(){document.querySelector(".hero-swiper")&&"undefined"!=typeof Swiper&&new Swiper(".hero-swiper",{effect:"fade",fadeEffect:{crossFade:!0},loop:!0,speed:900,autoplay:{delay:5500,disableOnInteraction:!1},pagination:{el:".hero-pagination",clickable:!0}})}function initBackToTop(){const e=document.getElementById("backToTop");e&&(window.addEventListener("scroll",()=>{e.classList.toggle("show",window.scrollY>400)}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))}function initLoader(){const e=document.getElementById("loader");if(!e)return;const t=()=>e.classList.add("hidden");"complete"!==document.readyState?window.addEventListener("load",t,{once:!0}):t()}function initContactForm(){const e=document.getElementById("contactForm");e&&e.addEventListener("submit",async t=>{t.preventDefault();const o={firstName:e.querySelector("#firstName").value.trim(),lastName:e.querySelector("#lastName").value.trim(),email:e.querySelector("#contactEmail").value.trim(),phone:e.querySelector("#contactPhone").value.trim(),orderNumber:e.querySelector("#orderNumber").value.trim(),message:e.querySelector("#contactMessage").value.trim()};try{await shareContactToWhatsApp(o),e.reset()}catch(t){console.error(t),openWhatsAppText(buildContactTextSummary(o)),e.reset()}})}function initApp(){updateCartUI(),setActiveNavLink(),initTopBar(),initHeroSwiper(),initBackToTop(),initContactForm()}documen